/**
 * Terra Drive vehicle catalogue. US-market configurations; SI except explicit
 * HP, LbFt, PSI and RPM fields. Published factory peaks/ratios are distinguished
 * from unmeasured tuning parameters. See docs/vehicle-sources.md.
 *
 * IMPORTANT: engine.curve is an interpolated simulation estimate constrained by
 * published torque and power peaks. Suspension coefficients, inertia, CG height,
 * carcass behaviour and soil interaction are NOT manufacturer test data.
 */
const LB_TO_KG = 0.45359237;
const LBFT_TO_NM = 1.3558179483314;
const IN_TO_M = 0.0254;
const MPH_TO_MS = 0.44704;
const nmAtHP = (hp, rpm) => hp * 745.6998715822702 / (rpm * Math.PI / 30);
const HUMMER_WHEEL_TORQUE_NM = 11500 * LBFT_TO_NM;
const HUMMER_MOTOR_TORQUE_NM = HUMMER_WHEEL_TORQUE_NM / (13.26 + 2 * 10.49);
const HUMMER_TOTAL_MOTOR_TORQUE_NM = 3 * HUMMER_MOTOR_TORQUE_NM;
const HUMMER_BASE_RPM = 830 * 745.6998715822702 / HUMMER_TOTAL_MOTOR_TORQUE_NM * 30 / Math.PI;

