export const VEHICLE_BY_ID = Object.fromEntries(VEHICLES.map(vehicle => [vehicle.id, vehicle]));

/** Readable source records for UI; unknown keys are filtered rather than linked. */
export const getVehicleSources = vehicle => (vehicle.sources || []).map(id => SOURCES[id]).filter(Boolean);

